/**
 * Value carried by the LocaleContext. `version` bumps on every language change to trigger re-renders.
 */
export interface LocaleContextValue {
    lang: string;
    version: number;
}
/**
 * Resolved locale value returned by `useLocale`.
 */
export interface LocaleValue {
    /**
     * The active language code.
     */
    lang: string;
    /**
     * The resolved messages for the active language.
     */
    messages: LocaleMessages;
    /**
     * Translates a key to the active language, with optional interpolation args.
     */
    t: (key: string, ...args: unknown[]) => string;
}
